    15	    const contextValue = { t: vi.fn().mockReturnValue('S’inscrire'), isLoading: true };
    16	    const wrapper = ({ children }: { children: React.ReactNode }) => (
    17	      <UiCopyContext.Provider value={contextValue}>{children}</UiCopyContext.Provider>
    18	    );
