########## overrides/app/components/uiCopyProvider/index.test.tsx ##########
     1	import React from 'react';
     2	import { describe, test, expect, vi, beforeEach } from 'vitest';
     3	import { renderHook } from '@testing-library/react';
     4	import { useContentfulEntries } from 'app/hooks/useContentful';
     5	import { useUiCopy } from 'app/hooks/useUiCopy';
     6	import type { UiCopyEntry } from 'app/types/contentful';
     7	import { UiCopyProvider } from './index';
     8	
     9	// useContentfulEntries's own fetch/asset-resolution logic is covered by its own consumers
    10	// (home/index.tsx exercises it live); mocking it here isolates this suite to UiCopyProvider's
    11	// own contract — reducing a list of entries into a key→value lookup, exposed via context.
    12	vi.mock('app/hooks/useContentful', () => ({
    13	  useContentfulEntries: vi.fn(),
    14	}));
    15	
    16	const mockUseContentfulEntries = vi.mocked(useContentfulEntries);
    17	
    18	const makeEntry = (key: string, value: string): UiCopyEntry => ({
    19	  sys: { id: `uicopy-${key}`, contentType: { sys: { id: 'uiCopy' } } },
    20	  fields: { title: key, key, value },
    21	});
    22	
    23	function renderWithProvider() {
    24	  const wrapper = ({ children }: { children: React.ReactNode }) => <UiCopyProvider>{children}</UiCopyProvider>;
    25	  return renderHook(() => useUiCopy(), { wrapper });
    26	}
    27	
    28	describe('UiCopyProvider', () => {
    29	  beforeEach(() => {
    30	    vi.clearAllMocks();
    31	  });
    32	
    33	  test('provides the CMS value for a key that exists', () => {
    34	    mockUseContentfulEntries.mockReturnValue({
    35	      data: [makeEntry('footer.subscribe.button', 'S’inscrire')],
    36	      isLoading: false,
    37	      error: null,
    38	    });
    39	
    40	    const { result } = renderWithProvider();
    41	
    42	    expect(result.current.t('footer.subscribe.button', 'Subscribe')).toBe('S’inscrire');
    43	  });
    44	
    45	  test('falls back to the provided default for a key that does not exist', () => {
    46	    mockUseContentfulEntries.mockReturnValue({
    47	      data: [makeEntry('other.key', 'value')],
    48	      isLoading: false,
    49	      error: null,
    50	    });
    51	
    52	    const { result } = renderWithProvider();
    53	
    54	    expect(result.current.t('footer.subscribe.button', 'Subscribe')).toBe('Subscribe');
    55	  });
    56	
    57	  test('falls back while loading, even if data is still null', () => {
    58	    mockUseContentfulEntries.mockReturnValue({ data: null, isLoading: true, error: null });
    59	
    60	    const { result } = renderWithProvider();
    61	
    62	    expect(result.current.isLoading).toBe(true);
    63	    expect(result.current.t('footer.subscribe.button', 'Subscribe')).toBe('Subscribe');
    64	  });
    65	
    66	  test('falls back on fetch error without throwing', () => {
    67	    mockUseContentfulEntries.mockReturnValue({ data: null, isLoading: false, error: new Error('network down') });
    68	
    69	    const { result } = renderWithProvider();
    70	
    71	    expect(result.current.t('footer.subscribe.button', 'Subscribe')).toBe('Subscribe');
    72	  });
    73	
    74	  test('t is referentially stable across re-renders when the underlying data is unchanged', () => {
    75	    const entries = [makeEntry('a', '1')];
    76	    mockUseContentfulEntries.mockReturnValue({ data: entries, isLoading: false, error: null });
    77	
    78	    const { result, rerender } = renderWithProvider();
    79	    const firstT = result.current.t;
    80	    rerender();
    81	
    82	    expect(result.current.t).toBe(firstT);
    83	  });
    84	});

