     5	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
     6	import { useContentfulClient } from 'app/hooks/useContentfulClient';
     7	import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry, RegionEntry } from 'app/types/contentful';
     8	import FooterContainer, { scopeToRegion } from './index';
