     8	
     9	// See footerNavColumn/index.test.tsx's identical mock for why: ZimmIcon pulls in the base SFCC
    10	// icons barrel, which throws under Vitest (SVG imports resolve to raw path strings here). No
    11	// assertion below depends on an icon's own content.
    12	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
    13	  ZimmIcon: (props: { 'aria-label'?: string; 'aria-hidden'?: boolean }) => (
    14	    <span aria-label={props['aria-label']} aria-hidden={props['aria-hidden']} />
    15	  ),
    16	}));
    17	
    18	// The real modal's focus-trap/portal mechanics are already covered by useZimmModal.test.tsx
    19	// (synthetic harness) and footer/index.stories.tsx's SubscribeModalOpen play (mutation-tested,
    20	// real browser). Stubbing it here keeps this suite scoped to ZimmSubscribeSection's own
    21	// contract — does it wire the right props into its children — rather than a second copy of
    22	// coverage that already exists elsewhere.
    23	vi.mock('app/components/ui-kits/organisms/zimmSubscribeModal', () => ({
    24	  ZimmSubscribeModal: ({
    25	    isOpen,
    26	    onClose,
    27	    onSubmit,
    28	  }: {
    29	    isOpen: boolean;
    30	    onClose: () => void;
    31	    onSubmit: (firstName: string, lastName: string) => void;
    32	  }) =>
    33	    isOpen ? (
    34	      <div role="dialog" aria-label="mock subscribe modal">
    35	        <button onClick={() => onSubmit('Jane', 'Smith')}>mock-continue</button>
    36	        <button onClick={onClose}>mock-cancel</button>
    37	      </div>
    38	    ) : null,
    39	}));
    40	
    41	// useSubscribeSection's own state machine (idle/unavailable/success/error transitions, modal
    42	// open/close, pending-signup capture) is exhaustively covered by useSubscribeSection.test.ts.
    43	// Mocking it here isolates this suite to ZimmSubscribeSection's own contract: given a state, does
    44	// it render the right branch, and does it correctly wire DOM events into the hook's handlers.
    45	vi.mock('app/hooks/useSubscribeSection', () => ({
    46	  useSubscribeSection: vi.fn(),
    47	}));
    48	
    49	// UiCopyProvider's own fetch/lookup logic is covered by its own test file; mocking useUiCopy
    50	// here isolates this suite to ZimmSubscribeSection's own contract rather than a second copy of
    51	// that coverage. Default matches the no-Provider fallback behaviour real callers see in
    52	// Storybook/production-before-content-exists.
    53	vi.mock('app/hooks/useUiCopy', () => ({
    54	  useUiCopy: vi.fn(),
    55	}));
    56	
    57	const mockUseSubscribeSection = vi.mocked(useSubscribeSection);
    58	const mockUseUiCopy = vi.mocked(useUiCopy);
    59	
    60	const baseProps = {
    61	  heading: 'Keep in Touch',
    62	  body: 'Sign up to stay up to date.',
    63	  privacyPolicyHref: '/privacy-policy',
    64	};
    65	
    66	function mockHook(overrides: Partial<ReturnType<typeof useSubscribeSection>> = {}) {
    67	  mockUseSubscribeSection.mockReturnValue({
    68	    submitState: 'idle',
    69	    modalOpen: false,
    70	    closeModal: vi.fn(),
    71	    handleEmailSubmit: vi.fn(),
    72	    handleModalSubmit: vi.fn(),
    73	    ...overrides,
    74	  });
    75	}
