    78	  beforeEach(() => {
    79	    vi.clearAllMocks();
    80	    mockHook();
    81	    mockUseUiCopy.mockReturnValue({ t: (_key: string, fallback: string) => fallback, isLoading: false });
    82	  });
    83	
    84	  test('idle: renders the email input and Subscribe button, no success/error message', () => {
    85	    render(<ZimmSubscribeSection {...baseProps} />);
    86	
    87	    expect(screen.getByRole('textbox', { name: /email/i })).toBeInTheDocument();
    88	    expect(screen.getByRole('button', { name: /subscribe/i })).toBeInTheDocument();
    89	    expect(screen.queryByText(/on the list/i)).not.toBeInTheDocument();
    90	    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
    91	  });
    92	
    93	  test('success: renders the success message, not the input', () => {
    94	    mockHook({ submitState: 'success' });
    95	    render(<ZimmSubscribeSection {...baseProps} />);
    96	
    97	    expect(screen.getByText(/on the list/i)).toBeInTheDocument();
    98	    expect(screen.queryByRole('textbox', { name: /email/i })).not.toBeInTheDocument();
    99	  });
